async function setupFourLineAward(){
 const refs=await seed();
 const created=await api("/api/procurement/rfqs",{method:"POST",body:{purchase_request_id:refs.fourLineRequestId,supplier_ids:[refs.supplierA,refs.supplierB],response_deadline:"2099-09-01",expected_version:1}});
 assert.equal(created.response.status,201,JSON.stringify(created.payload));
 const rfqId=created.payload.rfq_id;
 const issued=await api(`/api/procurement/rfqs/${rfqId}/issue`,{method:"POST",body:{expected_version:1}});
 assert.equal(issued.response.status,200,JSON.stringify(issued.payload));
 const detailBeforeQuotes=await api(`/api/procurement/rfqs/${rfqId}`);
 assert.equal(detailBeforeQuotes.response.status,200,JSON.stringify(detailBeforeQuotes.payload));
 const lines=detailBeforeQuotes.payload.data.lines;
 const quote=(supplierId,expected,price,delivery)=>api(`/api/procurement/rfqs/${rfqId}/quotes`,{method:"POST",body:{expected_version:expected,supplier_id:supplierId,supplier_quote_reference:`FOUR-${supplierId}`,valid_until:"2099-12-31",tax_included:false,freight_included:false,payment_terms:"月结 30 天",lines:lines.map(line=>({rfq_line_id:line.id,quoted_quantity:"10.000000",minimum_order_quantity:"10.000000",unit_price:`${price}.000000`,lead_time_days:10,promised_delivery_date:delivery}))}});
 const quoteA=await quote(refs.supplierA,2,12,"2099-09-21");
 assert.equal(quoteA.response.status,201,JSON.stringify(quoteA.payload));
 const quoteB=await quote(refs.supplierB,3,10,"2099-10-07");
 assert.equal(quoteB.response.status,201,JSON.stringify(quoteB.payload));
 const compared=await api(`/api/procurement/rfqs/${rfqId}/comparisons`,{method:"POST",body:{expected_version:4}});
 assert.equal(compared.response.status,201,JSON.stringify(compared.payload));
 const detailResult=await api(`/api/procurement/rfqs/${rfqId}`);
 assert.equal(detailResult.response.status,200,JSON.stringify(detailResult.payload));
 const detail=detailResult.payload.data,bySupplier=supplierId=>material=>material.offers.find(candidate=>Number(candidate.supplier_id)===supplierId);
 return{refs,rfqId,detail,bodyA:awardBody(detail,bySupplier(refs.supplierA),{reasonCode:"DELIVERY_PRIORITY",reason:"交期优先，避免项目延期；供应商A提前交付，供应商B已晚于需求日期。"}),bodyB:awardBody(detail,bySupplier(refs.supplierB),{reasonCode:"LATE_DELIVERY_ACCEPTED",reason:"接受最低价供应商延期交付，项目已确认风险。"})};
}
